        """letra conocida mala cuyo costo es asumible: sirve para renovar objetos del mundo."""
        v = self._val(k)
        if v is None: return False
        return bool(lev[0] + v[0] > 0.6 and lev[1] + v[1] > 0.6)

    def _quiere(self, k, lev):
